using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
            new() { Id = 4, Name = "English", Abbreviation = "ENG" },
            new() { Id = 5, Name = "History", Abbreviation = "HIST" }
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, Code = "CS101", Title = "Introduction to Programming",
                Description = "An introductory course covering fundamental programming concepts using Python. Students learn variables, control flow, functions, and basic data structures through hands-on projects.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. Her research focuses on CS education and pedagogy.", Email = "s.chen@university.edu" }
            },
            new()
            {
                Id = 2, Code = "CS301", Title = "Data Structures and Algorithms",
                Description = "Advanced study of data structures including trees, graphs, and hash tables. Covers algorithm design, complexity analysis, and optimization techniques.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Name = "Dr. James Park", Title = "Professor", Bio = "Dr. Park is a leading researcher in algorithmic complexity. He has published over 50 papers and authored two widely used textbooks.", Email = "j.park@university.edu" }
            },
            new()
            {
                Id = 3, Code = "CS420", Title = "Machine Learning",
                Description = "Introduction to machine learning theory and practice. Topics include supervised learning, neural networks, clustering, and model evaluation.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false,
                Instructor = new() { Name = "Dr. Maria Rodriguez", Title = "Assistant Professor", Bio = "Dr. Rodriguez joined from industry where she led ML teams at a major tech company. Her work bridges practical applications and theoretical foundations.", Email = "m.rodriguez@university.edu" }
            },
            new()
            {
                Id = 4, Code = "MATH201", Title = "Linear Algebra",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and inner product spaces with applications to science and engineering.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true,
                Instructor = new() { Name = "Dr. Alan Foster", Title = "Professor", Bio = "Dr. Foster specializes in applied linear algebra and numerical methods. He is known for making abstract concepts accessible to students.", Email = "a.foster@university.edu" }
            },
            new()
            {
                Id = 5, Code = "MATH301", Title = "Real Analysis",
                Description = "Rigorous treatment of the real number system, sequences and series, continuity, differentiation, and Riemann integration.",
                Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Alan Foster", Title = "Professor", Bio = "Dr. Foster specializes in applied linear algebra and numerical methods. He is known for making abstract concepts accessible to students.", Email = "a.foster@university.edu" }
            },
            new()
            {
                Id = 6, Code = "PHYS101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Calculus-based approach suitable for science and engineering majors.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Thu Lab 2:00–4:50 PM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true,
                Instructor = new() { Name = "Dr. Robert Kim", Title = "Associate Professor", Bio = "Dr. Kim's research is in experimental condensed matter physics. He has received multiple teaching excellence awards.", Email = "r.kim@university.edu" }
            },
            new()
            {
                Id = 7, Code = "PHYS301", Title = "Quantum Mechanics",
                Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, hydrogen atom, and perturbation theory.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Lisa Wang", Title = "Professor", Bio = "Dr. Wang is a theoretical physicist whose research explores quantum information and computation.", Email = "l.wang@university.edu" }
            },
            new()
            {
                Id = 8, Code = "ENG101", Title = "College Writing",
                Description = "Development of analytical reading and academic writing skills. Emphasis on argumentation, research methods, and clear prose.",
                Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Name = "Prof. Diana Hart", Title = "Senior Lecturer", Bio = "Prof. Hart has taught composition for 20 years and has published extensively on writing pedagogy.", Email = "d.hart@university.edu" }
            },
            new()
            {
                Id = 9, Code = "ENG350", Title = "American Literature",
                Description = "Survey of major American literary works from the colonial period to the present, exploring themes of identity, democracy, and cultural change.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Name = "Dr. Michael Torres", Title = "Associate Professor", Bio = "Dr. Torres specializes in 20th-century American fiction and has authored three books on the American literary canon.", Email = "m.torres@university.edu" }
            },
            new()
            {
                Id = 10, Code = "HIST101", Title = "World History to 1500",
                Description = "A global survey of human civilizations from ancient times through the late medieval period, covering political, social, and cultural developments.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, DepartmentName = "History", IsFeatured = false,
                Instructor = new() { Name = "Dr. Karen Wright", Title = "Professor", Bio = "Dr. Wright is an award-winning historian specializing in ancient Mediterranean civilizations and cross-cultural exchange.", Email = "k.wright@university.edu" }
            }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

