@page "/courses"
@inject CourseCatalog.Services.CatalogService Catalog

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="filter-bar">
    <input type="text" name="search" value="@Search" placeholder="Search courses, instructors..." class="search-input" />
    <select name="departmentId" class="filter-select">
        <option value="">All Departments</option>
        @foreach (var dept in Catalog.GetDepartments())
        {
            <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
        }
    </select>
    <button type="submit" class="btn-primary">Search</button>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}
else
{
    <p class="result-count">Showing @courses.Count course(s)</p>
    <div class="course-list">
        @foreach (var course in courses)
        {
            <div class="course-row">
                <div class="course-row-main">
                    <span class="badge">@course.Code</span>
                    <a href="/courses/@course.Id"><strong>@course.Title</strong></a>
                </div>
                <div class="course-row-meta">
                    <span>@course.DepartmentName</span>
                    <span>@course.Credits cr.</span>
                    <span>@course.Instructor.Name</span>
                </div>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@inject CourseCatalog.Services.CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist. <a href="/courses">Back to catalog</a></p>
}
else
{
    <PageTitle>@course.Title - University Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/courses">Courses</a> &rsaquo;
        <a href="/courses?departmentId=@course.DepartmentId">@course.DepartmentName</a> &rsaquo;
        <span>@course.Code</span>
    </nav>

    <article class="course-detail">
        <header>
            <span class="badge badge-lg">@course.Code</span>
            <h1>@course.Title</h1>
            <p class="meta">@course.DepartmentName &middot; @course.Credits credits</p>
        </header>

        <section>
            <h2>Description</h2>
            <p>@course.Description</p>
        </section>

        <section>
            <h2>Schedule</h2>
            <p>@course.Schedule</p>
        </section>

        <section class="instructor-card">
            <h2>Instructor</h2>
            <h3>@course.Instructor.Name</h3>
            <p class="instructor-title">@course.Instructor.Title</p>
            <p>@course.Instructor.Bio</p>
            <p><a href="mailto:@course.Instructor.Email">@course.Instructor.Email</a></p>
        </section>

        <div class="actions">
            <a href="/enroll?courseId=@course.Id" class="btn-primary">Request Enrollment</a>
            <a href="/courses" class="btn-secondary">Back to Catalog</a>
        </div>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private CourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

@page "/enroll"
@inject CourseCatalog.Services.CatalogService Catalog

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>Request Submitted!</h2>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
        <p>You will receive a confirmation at your university email within 2 business days.</p>
        <a href="/courses" class="btn-primary">Back to Catalog</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="enrollment-form">
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="form-group">
            <label for="fullName">Full Name</label>
            <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
            <ValidationMessage For="() => Model.FullName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., CS123456" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-control">
                <option value="0">-- Select a course --</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn-primary">Submit Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private CourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        submitted = true;
    }
}

